'use client';

import { useEffect, useState } from 'react';
import Layout from '@/components/layout/layout';
import AuthGuard from '@/components/auth/auth-guard';
import { 
  ChartBarIcon, 
  BuildingOfficeIcon, 
  ShoppingBagIcon, 
  ArrowTrendingUpIcon,
  ArchiveBoxIcon,
  ExclamationTriangleIcon
} from '@heroicons/react/24/outline';
import { api } from '@/lib/api';
import { formatCurrency, formatNumber } from '@/lib/utils';
import { DashboardSummaryResponse, BranchResponse } from '@/types';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';

export default function DashboardReportsPage() {
  const [summary, setSummary] = useState<DashboardSummaryResponse | null>(null);
  const [branches, setBranches] = useState<BranchResponse[]>([]);
  const [selectedBranchId, setSelectedBranchId] = useState<string>('all');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true);
        const [summaryRes, branchesRes] = await Promise.all([
          api.dashboard.getSummary(),
          api.branches.getAll()
        ]);

        if (summaryRes.success) setSummary(summaryRes.data);
        if (branchesRes.success) setBranches(branchesRes.data);
      } catch (error) {
        console.error('Error fetching report data:', error);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  const currentBranchSummary = selectedBranchId === 'all' 
    ? null 
    : summary?.branchSummaries.find(b => b.branchId === selectedBranchId);

  return (
    <AuthGuard>
      <Layout>
        <div className="space-y-6">
          <div className="flex justify-between items-center">
            <div>
              <h1 className="text-2xl font-bold text-primary">Dashboard Reports</h1>
              <p className="text-sm text-text-secondary">Quick overview of branch performance and inventory</p>
            </div>
            
            <div className="flex items-center gap-3">
              <span className="text-sm font-medium text-text-secondary">Branch:</span>
              <Select value={selectedBranchId} onValueChange={setSelectedBranchId}>
                <SelectTrigger className="w-[200px]">
                  <SelectValue placeholder="Select Branch" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Branches</SelectItem>
                  {branches.map(branch => (
                    <SelectItem key={branch.id} value={branch.id}>{branch.name}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>

          {loading ? (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
              {[...Array(4)].map((_, i) => (
                <div key={i} className="h-32 bg-surface animate-pulse rounded-xl" />
              ))}
            </div>
          ) : (
            <>
              {/* Stats Overview */}
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                <Card className="bg-card">
                  <CardHeader className="pb-2">
                    <CardTitle className="text-xs font-bold text-text-secondary uppercase tracking-wider flex items-center gap-2">
                      <ShoppingBagIcon className="w-4 h-4 text-primary" />
                      {selectedBranchId === 'all' ? 'Total Products' : 'Branch Products'}
                    </CardTitle>
                  </CardHeader>
                  <CardContent>
                    <p className="text-2xl font-black text-primary">
                      {selectedBranchId === 'all' ? summary?.totalProducts : currentBranchSummary?.totalProducts || 0}
                    </p>
                  </CardContent>
                </Card>

                <Card className="bg-card">
                  <CardHeader className="pb-2">
                    <CardTitle className="text-xs font-bold text-text-secondary uppercase tracking-wider flex items-center gap-2">
                      <ArchiveBoxIcon className="w-4 h-4 text-success" />
                      Inventory Value
                    </CardTitle>
                  </CardHeader>
                  <CardContent>
                    <p className="text-2xl font-black text-success">
                      {formatCurrency(selectedBranchId === 'all' ? summary?.totalInventoryValue || 0 : currentBranchSummary?.totalStockValue || 0)}
                    </p>
                  </CardContent>
                </Card>

                <Card className="bg-card">
                  <CardHeader className="pb-2">
                    <CardTitle className="text-xs font-bold text-text-secondary uppercase tracking-wider flex items-center gap-2">
                      <ArrowTrendingUpIcon className="w-4 h-4 text-info" />
                      Today's Sales
                    </CardTitle>
                  </CardHeader>
                  <CardContent>
                    <p className="text-2xl font-black text-info">
                      {selectedBranchId === 'all' ? formatCurrency(summary?.todaySalesTotal || 0) : '---'}
                    </p>
                    {selectedBranchId === 'all' && (
                      <p className="text-[10px] text-text-secondary mt-1 font-bold">{summary?.todaySalesCount} transactions today</p>
                    )}
                  </CardContent>
                </Card>

                <Card className="bg-card">
                  <CardHeader className="pb-2">
                    <CardTitle className="text-xs font-bold text-text-secondary uppercase tracking-wider flex items-center gap-2">
                      <ExclamationTriangleIcon className="w-4 h-4 text-error" />
                      Low Stock Alerts
                    </CardTitle>
                  </CardHeader>
                  <CardContent>
                    <p className="text-2xl font-black text-error">
                      {selectedBranchId === 'all' ? summary?.totalLowStockItems : currentBranchSummary?.lowStockCount || 0}
                    </p>
                  </CardContent>
                </Card>
              </div>

              {/* Detailed Sections */}
              <Tabs defaultValue="inventory" className="w-full">
                <TabsList className="bg-surface p-1">
                  <TabsTrigger value="inventory">Inventory Summary</TabsTrigger>
                  <TabsTrigger value="branches" disabled={selectedBranchId !== 'all'}>Branch Performance</TabsTrigger>
                </TabsList>
                
                <TabsContent value="inventory" className="mt-4">
                  <Card>
                    <CardHeader>
                      <CardTitle className="text-lg font-bold">Stock Status Breakdown</CardTitle>
                    </CardHeader>
                    <CardContent>
                      <div className="space-y-4">
                        <div className="flex justify-between items-center p-4 bg-surface/50 rounded-xl border border-divider/40">
                          <div>
                            <p className="text-sm font-bold text-primary">In Stock Units</p>
                            <p className="text-xs text-text-secondary">Total physical units currently on hand</p>
                          </div>
                          <p className="text-xl font-black text-primary">
                            {formatNumber(selectedBranchId === 'all' ? summary?.branchSummaries.reduce((a, b) => a + b.totalUnits, 0) || 0 : currentBranchSummary?.totalUnits || 0)}
                          </p>
                        </div>
                        <div className="flex justify-between items-center p-4 bg-error/5 rounded-xl border border-error/10">
                          <div>
                            <p className="text-sm font-bold text-error">Out of Stock Items</p>
                            <p className="text-xs text-text-secondary">Products with zero quantity remaining</p>
                          </div>
                          <p className="text-xl font-black text-error">
                            {selectedBranchId === 'all' ? summary?.totalOutOfStockItems : currentBranchSummary?.outOfStockCount || 0}
                          </p>
                        </div>
                      </div>
                    </CardContent>
                  </Card>
                </TabsContent>

                <TabsContent value="branches" className="mt-4">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {summary?.branchSummaries.map(branch => (
                      <Card key={branch.branchId} className="hover:border-primary/30 transition-colors">
                        <CardHeader className="pb-2 border-b border-divider/40">
                          <div className="flex justify-between items-center">
                            <CardTitle className="text-md font-bold text-primary">{branch.branchName}</CardTitle>
                            <span className="text-[10px] font-black uppercase tracking-widest px-2 py-1 bg-surface rounded-lg text-text-secondary">
                              {branch.branchType}
                            </span>
                          </div>
                        </CardHeader>
                        <CardContent className="pt-4 grid grid-cols-2 gap-4">
                          <div>
                            <p className="text-[10px] font-bold text-text-secondary uppercase">Stock Value</p>
                            <p className="text-lg font-black text-success">{formatCurrency(branch.totalStockValue)}</p>
                          </div>
                          <div>
                            <p className="text-[10px] font-bold text-text-secondary uppercase">Unique SKUs</p>
                            <p className="text-lg font-black text-primary">{branch.totalProducts}</p>
                          </div>
                          <div>
                            <p className="text-[10px] font-bold text-text-secondary uppercase">Low Stock</p>
                            <p className="text-lg font-black text-error">{branch.lowStockCount}</p>
                          </div>
                          <div>
                            <p className="text-[10px] font-bold text-text-secondary uppercase">Total Units</p>
                            <p className="text-lg font-black text-info">{formatNumber(branch.totalUnits)}</p>
                          </div>
                        </CardContent>
                      </Card>
                    ))}
                  </div>
                </TabsContent>
              </Tabs>
            </>
          )}
        </div>
      </Layout>
    </AuthGuard>
  );
}
